import sys
from collections import deque

def check_connectivity(n, edges, s, t, removed):
    graph = [[] for _ in range(n + 1)]
    for i, (u, v, w) in enumerate(edges):
        if i not in removed:
            graph[u].append(v)
            graph[v].append(u)

    visited = [False] * (n + 1)
    queue = deque([s])
    visited[s] = True

    while queue:
        u = queue.popleft()
        if u == t:
            return True
        for v in graph[u]:
            if not visited[v]:
                visited[v] = True
                queue.append(v)

    return False

def parse_input(input_str):
    lines = input_str.strip().split('\n')
    first_line = lines[0].split()
    n, m = int(first_line[0]), int(first_line[1])

    second_line = lines[1].split()
    s, t = int(second_line[0]), int(second_line[1])

    edges = []
    for i in range(2, 2 + m):
        parts = lines[i].split()
        u, v, w = int(parts[0]), int(parts[1]), int(parts[2])
        edges.append((u, v, w))

    return n, m, s, t, edges

def solution(input_str):
    n, m, s, t, edges = parse_input(input_str)

    # Check option 0: no roads closed
    if not check_connectivity(n, edges, s, t, set()):
        return "0\n0\n"

    min_cost = float('inf')
    best_edges = None

    # Check option 1: close 1 road
    for i in range(m):
        if not check_connectivity(n, edges, s, t, {i}):
            cost = edges[i][2]
            if cost < min_cost:
                min_cost = cost
                best_edges = [i + 1]

    if best_edges is not None:
        return f"{min_cost}\n{len(best_edges)}\n{' '.join(map(str, best_edges))}\n"

    # Check option 2: close 2 roads
    for i in range(m):
        if edges[i][2] >= min_cost:
            continue
        for j in range(i + 1, m):
            if edges[i][2] + edges[j][2] >= min_cost:
                continue
            removed = {i, j}
            if not check_connectivity(n, edges, s, t, removed):
                cost = edges[i][2] + edges[j][2]
                if cost < min_cost:
                    min_cost = cost
                    best_edges = [i + 1, j + 1]

    if best_edges is not None:
        return f"{min_cost}\n{len(best_edges)}\n{' '.join(map(str, best_edges))}\n"

    return "-1"

