def solution(input_str):
    lines = input_str.strip().split('\n')

    n, m = map(int, lines[0].split())
    a = list(map(int, lines[1].split()))
    b = list(map(int, lines[2].split()))

    parent = list(map(int, lines[3:]))
    for line in lines[3:]:
        if line.strip() == '':
            continue
        parent.append(line)

    roads = []
    idx = 3
    i = 0
    while i < n:
        if idx >= len(lines):
            break
        try:
            parts = lines[idx].strip().split()
            if len(parts) == 2:
                roads.append((int(parts[0]), int(parts[1])))
                idx += 1
                continue
            i += 1
            if i <= n:
                i = idx + 1 if idx < len(lines) else i + 1
        except:
            idx += 1

    # Actually let me properly parse lines starting from line 3
    city_lines = input_str.split('\n')
    n, m = map(int, city_lines[0].split())
    a = list(map(int, city_lines[1].split()))
    b = list(map(int, city_lines[2].split()))

    adj = {}
    for i in range(m):
        p, q = map(int, city_lines[3 + i].split())
        adj[frozenset({p, q})] = (p, q)

    total_b = sum(b)

    # Build max flow network
    source = 0
    sink = n + 1
    capacity = [[0] * (sink + 2) for _ in range(sink + 2)]
    flow = [[0] * (sink + 2) for _ in range(sink + 2)]
    graph = [[] for _ in range(sink + 2)]

    def add_edge(u, v, cap):
        graph[u].append(len(graph[v]))
        graph[v].append(len(graph[u]))
        capacity[u][len(graph[u]) - 1] = cap
        capacity[v][len(graph[v]) - 1] = 0

    # Source to each city
    for i in range(1, n + 1):
        add_edge(source, i, a[i-1])

    # Each city to sink
    for i in range(n):
        add_edge(1 + i, sink, b[i])

    # Cities to neighbors (including self)
    for i in range(1, n + 1):
        graph[i].append(i)
        capacity[i][len(graph[i]) - 1] = float('inf')
        capacity[i][len(graph[i]) - 1] = float('inf')

    # BFS for level graph
    def bfs():
        level = [-1] * (sink + 2)
        level[source] = 0
        queue = [source]
        while queue:
            u = queue.pop(0)
            for v_idx in graph[u]:
                if capacity[u][v_idx] + flow[u][graph[u][v_idx]] > 0 and level[graph[u][v_idx]] == -1:
                    level[graph[u][v_idx]] = level[u] + 1
                    queue.append(graph[u][v_idx])
        return level

    # DFS for blocking flow
    def dfs(u, t, pushed, level):
        if pushed == 0:
            return 0
        queue = [u]
        parent_edge = {}
        while queue:
            u = queue.pop(0)
            for v_idx in graph[u]:
                v = graph[u][v_idx]
                if level[v] != level[u] + 1 or capacity[u][v_idx] + flow[u][v_idx] == 0:
                    continue
                push = dfs(v, t, min(pushed, capacity[u][v_idx] + flow[u][v_idx]), level)
                if push > 0:
                    flow[u][v] += push
                    flow[v][u] -= push
                    return push
                queue.append(v)
        return 0

    # Better DFS using path tracking
    def dfs2(u, t):
        if u == t:
            return float('inf')
        visited.add(u)
        for v_idx in graph[u]:
            v = graph[u][v_idx]
            if level[v] != level[u] + 1:
                continue
            if v in visited:
                continue
            if capacity[u][v_idx] + flow[u][v_idx] == 0:
