            pushed = dfs2(v, t)
            if pushed == float('inf'):
                continue
            min_flow = capacity[u][v_idx] + flow[u][v_idx]
            flow[u][v_idx] += pushed
            flow[v][u] -= pushed
            return pushed
        return 0

    # Simplified Dinic's algorithm
    level = [0] * (n + 2)
    total_flow = 0

    def dinic():
        nonlocal total_flow
        while True:
            level = bfs()
            if level[sink] == -1:
                break

            ptr = [0] * (n + 2)

            def dfs(u, pushed):
                if pushed == 0 or u == sink:
                    return pushed
                for i in range(ptr[u], len(graph[u])):
                    ptr[u] = i
                    v = graph[u][i]
                    if level[v] != level[u] + 1:
