    # Extract solution matrix
    result = [["0"] * (n + 1) for _ in range(n + 1)]

    for i in range(1, n + 1):
        for j_idx in graph[i + n]:
            if capacity[i][j_idx] == float('inf') and j_idx <= n + 1:
                continue
        for j in range(i + 1):
            if graph[i + j_idx] and graph[i + 1] == j_idx] <= n + 1 and capacity[i][j_idx] == float('inf') and level[sink] == -1:
                flow_val = flow[i][graph[i][j_idx]]
                if flow_val > 0:
