def modPower(base, exp, mod):
    result = 1
    while exp > 0:
        if exp & 1:
            result = (result * base) % mod
        base = (base * base) % mod
        exp >>= 1
    return result

def modInverse(n, mod):
    return modPower(n, mod - 2, mod)

def nCr(n, r, mod):
    if r < 0 or r > n:
        return 0
    num = 1
    den = 1
    for i in range(r):
        num = (num * (n - i)) % mod
        den = (den * (i + 1)) % mod
    return (num * modInverse(den, mod)) % mod

