    """
    Groups sheep that have overlapping intervals using Union-Find,
    then outputs sheep in component order with sorted values within each component.
    """
    import sys

    if not input_str.strip():
        return ""

    lines = input_str.strip().split('\n')
    n = int(lines[0])
    intervals = []
    for i in range(1, n + 1):
        parts = lines[i].split()
        l, r = int(parts[0]), int(parts[1])
        intervals.append((l, r))

    # Union-Find data structure
    parent = list(range(n + 1))

    def find(x):
        root = x
        while parent[root] != root:
            root = parent[root]
        # Path compression
        curr = x
        while curr != root:
            next_node = parent[curr]
            parent[curr] = root
            curr = next_node
        return root

    def union(i, j):
        root_i = find(i)
        root_j = find(j)
        if root_i != root_j:
            parent[root_i] = root_j

    # Union sheep whose intervals overlap
    for i in range(n):
        for j in range(i + 1, n):
            # Check if intervals [l1, r1] and [l2, r2] overlap
            if max(intervals[i][0], intervals[j][0]) <= min(intervals[i][1], intervals[j][1]):
                union(i + 1, j + 1)

    # Group sheep by their component (root in Union-Find)
    groups = {}
    for i in range(1, n + 1):
        root = find(i)
        if root not in groups:
            groups[root] = []
        groups[root].append(i)

    # Build result: sort sheep within each group and output in discovery order
    result = []
    for root in groups.keys():
        sheep_list = groups[root]
        sheep_list.sort()
        result.extend(sheep_list)

