    # Calculate area using shoelace formula
    def polygon_area(pts):
        n_pts = len(pts)
        if n_pts < 3:
            return 0.0
        area = 0.0
        for i in range(n_pts):
            x1, y1 = pts[i]
            x2, y2 = pts[(i + 1) % n_pts]
            area += x1 * y2 - x2 * y1
        return abs(area) / 2.0

    # Find edge intersection with vertical line x=f
    def intersect_edge(p1, p2, f):
        """Find intersection of edge p1-p2 with x=f, return None if parallel or outside segment"""
        x1, y1 = p1
        x2, y2 = p2
        if abs(x2 - x1) < 1e-9:
            return None  # Vertical edge, no proper intersection
        t = (f - x1) / (x2 - x1)
        if -1e-12 <= t <= 1 + 1e-12:
            y = y1 + t * (y2 - y1)
            return (f, y)
        return None

    def split_polygon_at(points, f):
        """Split polygon into left and right polygons at vertical line x=f"""
        n_pts = len(points)
        left = []
        right = []

