            break

        n, m = map(int, lines[line_idx].split())
        line_idx += 1

        # Read color grid
        color_grid = []
        for i in range(n):
            color_grid.append(lines[line_idx])
            line_idx += 1

        # Read direction grid
        direction_grid = []
        for i in range(n):
            direction_grid.append(lines[line_idx])
            line_idx += 1

        # Build graph - each cell maps to exactly one next cell
        next_pos = {}
        for i in range(n):
            for j in range(m):
                d = direction_grid[i] if i < len(direction_grid) else ""
                if d and j < len(d):
                    ch = d[j]
                    if ch == 'U':
                        ni, nj = i - 1, j
                    elif ch == 'D':
                        ni, nj = i + 1, j
                    elif ch == 'L':
                        ni, nj = i, j - 1
                    else:  # 'R'
                        ni, nj = i, j + 1
                    next_pos[(i, j)] = (ni, nj)

        # Find all cycle memberships for each cell
        in_cycle = [[False] * m for _ in range(n)]

        for start_i in range(n):
            for start_j in range(m):
                # Trace path from this cell
                path = []
                curr = (start_i, start_j)
                pos_to_idx = {}

                while curr not in pos_to_idx:
                    pos_to_idx[curr] = len(path)
                    path.append(curr)
                    curr = next_pos.get(curr, curr)

                # If curr is in current path, we found a cycle
                if curr in pos_to_idx:
                    cycle_start_idx = pos_to_idx[curr]
                    for idx in range(cycle_start_idx, len(path)):
                        ii, jj = path[idx]
                        if 0 <= ii < n and 0 <= jj < m:
                            in_cycle[ii][jj] = True

        # Count cells that are in cycles (this represents maximum safe robot positions)
        total_cycle_cells = sum(1 for i in range(n) for j in range(m) if in_cycle[i][j])

        # Count black cells ('0') that are in cycles
        total_black_in_cycle = sum(1 for i in range(n) for j in range(m) 
                                   if color_grid[i] and j < len(color_grid[i]) 
                                   and color_grid[i][j] == '0' 
                                   and in_cycle[i][j])

        ans.append(f"{total_cycle_cells} {total_black_in_cycle}")

    return '\n'.join(ans)

