    queries = []
    for _ in range(q):
        v, s, t = map(int, lines[idx].split())
        idx += 1
        queries.append((v, s, t))

    # Tarjan's algorithm for SCC (recursive)
    dfn = [0] * (n + 1)
    low = [0] * (n + 1)
    scc_id = [0] * (n + 1)
    timer = 0
    scc_cnt = 0
    stack = []
    on_stack = [False] * (n + 1)

    def tarjan(u):
        nonlocal timer, scc_cnt
        dfn[u] = low[u] = timer
        timer += 1
        stack.append(u)
        on_stack[u] = True

        for v, w in adj[u]:
            if dfn[v] == 0:
                tarjan(v)
                low[u] = min(low[u], low[v])
            elif on_stack[v]:
                low[u] = min(low[u], dfn[v])

        if low[u] == dfn[u]:
            scc_cnt += 1
            while True:
                v = stack.pop()
                on_stack[v] = False
                scc_id[v] = scc_cnt
                if v == u:
                    break

    for i in range(1, n + 1):
        if dfn[i] == 0:
            tarjan(i)

    # Compute GCD of all cycle lengths in each SCC
    scc_gcd = {}

    for scc in range(1, scc_cnt + 1):
        scc_nodes = [i for i in range(1, n + 1) if scc_id[i] == scc]
        if len(scc_nodes) <= 1:
            scc_gcd[scc] = 0
            continue

        root = scc_nodes[0]
        dist = {root: 0}
        g = 0

        def dfs(u, d):
            nonlocal g
            for v, w in adj[u]:
                if scc_id[v] != scc_id[u]:
                    continue
                if v in dist:
                    cycle_len = d + w - dist[v]
                    g = gcd(g, cycle_len)
                else:
                    dist[v] = d + w
                    dfs(v, d + w)

        dfs(root, 0)
        scc_gcd[scc] = g

    results = []
    for v, s, t in queries:
        if s == 0:
            results.append("YES")
        else:
            scc = scc_id[v]
            g = scc_gcd.get(scc, 0)
            if g == 0:
                results.append("NO")
            elif (t - s) % g == 0:
                results.append("YES")
            else:
                results.append("NO")

    return '\n'.join(results)

